document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("boiler-power-form"),t=document.getElementById("boiler-power-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("boiler-area").value),o=parseFloat(document.getElementById("boiler-height").value),i=parseFloat(document.getElementById("boiler-insulation").value),a=parseFloat(document.getElementById("boiler-climate").value);if(n<=0||o<=0)return t.textContent="Please enter home area and ceiling height.",void 0;let l=n*i;const r=o/8;l*=r;const s=l*a,c=1.15*s,d=c/1e5*800*1.2,u=c/14e4*800*3,m=c/3412*2e3*.12,p={30:"Excellent insulation",40:"Good insulation",50:"Average insulation",60:"Poor insulation"}[i]||"Custom insulation",g={.8:"Very hot climate",1:"Warm/mixed climate",1.2:"Cool/cold climate",1.4:"Very cold climate"}[a]||"Custom climate";t.innerHTML=`\n        <div class="result-section">\n          <h4>Recommended Boiler Size:</h4>\n          <p><strong>${Math.round(c).toLocaleString()} BTU/hour</strong></p>\n          <p>Base calculation: ${Math.round(s).toLocaleString()} BTU + 15% safety factor</p>\n        </div>\n        <div class="result-breakdown">\n          <h4>Calculation Details:</h4>\n          <p>Area: ${n.toLocaleString()} sq ft</p>\n          <p>Ceiling height: ${o} ft (factor: ${r.toFixed(2)})</p>\n          <p>${p}: ${i} BTU/sq ft</p>\n          <p>${g}: ×${a} adjustment</p>\n        </div>\n        <div class="result-costs">\n          <h4>Estimated Annual Fuel Costs:</h4>\n          <p><strong>Natural Gas:</strong> ~$${Math.round(d).toLocaleString()}</p>\n          <p><strong>Heating Oil:</strong> ~$${Math.round(u).toLocaleString()}</p>\n          <p><strong>Electric:</strong> ~$${Math.round(m).toLocaleString()}</p>\n        </div>\n        <div class="result-tips">\n          <p><em>🔥 Consider a condensing boiler for 15% better efficiency</em></p>\n          <p><em>🏠 Improve insulation to reduce boiler size requirements</em></p>\n          <p><em>⚡ Get a Manual J calculation for precise sizing</em></p>\n        </div>\n      `})});